package br.com.pelotavision;
import static org.junit.Assert.*;import org.junit.Test;import java.util.*;
public class CoverageSuggestionTest {
 static final int W=400,H=100;static final double[] X={40,120,200,280,360};
 static DetectionEvidence evidence(){byte[] mask=new byte[W*H];for(int y=0;y<H;y++)for(int x=0;x<W;x++)for(double cx:X)if(Math.hypot(x+.5-cx,y+.5-50)<=25){mask[y*W+x]=1;break;}return new DetectionEvidence(W,H,W,H,mask,true,true,100,70);}
 static PelletDetector.Detection ellipse(int i,boolean fitted){PelletDetector.Detection seed=new PelletDetector.Detection(X[i],50,25,Math.PI*625,1,false,!fitted);return new PelletDetector.Detection(seed,X[i],50,25,25,0,fitted,fitted?.9:Double.NaN,fitted?.015:Double.NaN,false,!fitted);}
 static PelletDetector.Result result(PelletDetector.Detection... objects){return new PelletDetector.Result(Arrays.asList(objects),W,H,objects.length,1,false,"coverage-test");}
 static DetectionAssessment.Context context(){return new DetectionAssessment.Context(null,W,H,null,5);}
 static double score(PelletDetector.Result r,DetectionEvidence e){DetectionAssessment.Metrics m=DetectionAssessment.measure(r,context());return DetectionAssessment.coverageScore(m,e.coverage(e.map(r),context()),1,false);}
 @Test public void completeLocalizationOutranksSmallPerfectSubsetWithoutInventingFits(){DetectionEvidence e=evidence();PelletDetector.Result subset=result(ellipse(0,true),ellipse(1,true)),complete=result(ellipse(0,true),ellipse(1,true),ellipse(2,false),ellipse(3,false),ellipse(4,false));assertTrue(score(complete,e)>score(subset,e)+20);assertEquals(2,ShapeStatistics.of(complete).included);assertFalse(complete.circles.get(2).ellipseFitted);assertTrue(complete.circles.get(2).needsReview);assertEquals(5,complete.circles.size());assertEquals(50,complete.circles.get(2).radius*2,0);}
 @Test public void duplicateMarkersNeverMultiplyCoverage(){DetectionEvidence e=evidence();PelletDetector.Result single=result(ellipse(0,true)),duplicate=result(ellipse(0,true),ellipse(0,true),ellipse(0,true));DetectionEvidence.Coverage a=e.coverage(e.map(single),context()),b=e.coverage(e.map(duplicate),context());assertEquals(a.covered,b.covered,0);assertEquals(a.validated,b.validated,0);assertTrue(score(single,e)>score(duplicate,e));}
 @Test public void coverageRespectsRoiAndUserReferenceFootprint(){DetectionEvidence e=evidence();PelletDetector.Result r=result(ellipse(0,true),ellipse(1,true));DetectionEvidence.Map map=e.map(r);InterestRegion roi=new InterestRegion(InterestRegion.Shape.RECTANGLE,10,10,150,90);DetectionEvidence.Coverage inside=e.coverage(map,new DetectionAssessment.Context(null,W,H,roi,5));assertEquals(1,inside.covered,1e-12);ObjectCalibration.Reference ref=ObjectCalibration.select(r.circles.get(0),1,1,ObjectCalibration.Measure.STANDARD_SPHERE,12,true,W,H,W,H);DetectionEvidence.Coverage excluded=e.coverage(map,new DetectionAssessment.Context(Granulometry.Settings.selectedObject(ref,1,true,false),W,H,null,5));assertEquals(.25,excluded.covered,.001);assertEquals(1,ref.fullImageId);assertEquals(2,r.circles.size());}
 @Test public void reRankingKeepsMapsAndMeasuredReferenceAndUsesBothMethodsEarly(){List<DetectionTuner.Option> options=DetectionTuner.options(new DetectionTuner.Option(3,75,false));assertEquals(24,options.size());assertTrue(options.get(1).legacy);assertEquals(1,options.get(1).profile);Set<String> seen=new HashSet<>();for(DetectionTuner.Option o:options)assertTrue(seen.add(o.id));for(int p=0;p<4;p++)for(boolean legacy:new boolean[]{false,true})for(int s:new int[]{55,75,90})assertTrue(seen.contains(new DetectionTuner.Option(p,s,legacy).id));}
 @Test public void unsupportedImageEvidenceIsExplicitlyUnavailable(){byte[] mask=new byte[W*H];DetectionEvidence e=new DetectionEvidence(W,H,W,H,mask,false,true,0,0);DetectionEvidence.Coverage c=e.coverage(e.map(result(ellipse(0,true))),context());assertFalse(c.available);assertEquals(0,c.covered,0);}
 @Test public void illuminationTrendEstimateIsIndependentOfCandidateCounts()throws Exception{
  int w=160,h=100;byte[] values=new byte[w*h];for(int y=0;y<h;y++)for(int x=0;x<w;x++)values[y*w+x]=(byte)(60+80*x/(double)w);
  java.lang.reflect.Method method=DetectionEvidence.class.getDeclaredMethod("backgroundPlane",byte[].class,int.class,int.class,boolean.class);method.setAccessible(true);double[] plane=(double[])method.invoke(null,values,w,h,true);
  assertEquals(80,plane[1],3);assertEquals(0,plane[2],1e-9);assertTrue(Math.abs(plane[1])>24);
 }
}
